import { useEffect, useId, useRef, useState } from "react";
import { ArrowDown, Check, Circle, Square, Terminal, TriangleAlert, X } from "lucide-react";
import { BfButton } from "./BfButton";
import "./execution.css";

export type ExecutionStatus = "queued" | "running" | "succeeded" | "failed" | "cancelled";
export type StreamConnection = "connected" | "reconnecting" | "disconnected";
export interface ExecutionEvent { id: string; time: string; level: "info" | "success" | "warning" | "error"; message: string }
export interface BfExecutionStreamProps {
  title: string;
  executionId: string;
  status: ExecutionStatus;
  connection: StreamConnection;
  events: ExecutionEvent[];
  onReconnect?: () => void;
}
const labels: Record<ExecutionStatus, string> = { queued: "Queued", running: "Running", succeeded: "Succeeded", failed: "Failed", cancelled: "Cancelled" };
const icons = { queued: Circle, running: Terminal, succeeded: Check, failed: X, cancelled: Square };

/** Presentational stream. The caller owns transport, ordering, retention and execution state. */
export function BfExecutionStream({ title, executionId, status, connection, events, onReconnect }: BfExecutionStreamProps) {
  const headingId = useId();
  const viewport = useRef<HTMLDivElement>(null);
  const following = useRef(true);
  const [isFollowing, setFollowing] = useState(true);
  const lastEventId = events[events.length - 1]?.id;
  const StatusIcon = icons[status];
  useEffect(() => {
    following.current = true;
    setFollowing(true);
  }, [executionId]);
  useEffect(() => {
    if (following.current && viewport.current) viewport.current.scrollTop = viewport.current.scrollHeight;
  }, [lastEventId, executionId]);
  function followLatest() {
    following.current = true;
    setFollowing(true);
    if (viewport.current) viewport.current.scrollTop = viewport.current.scrollHeight;
  }
  const emptyMessage = status === "queued" ? "Waiting for execution to start." : status === "running" ? "Waiting for the first event." : "No output was recorded for this execution.";
  return (
    <section className="bds-execution" aria-labelledby={headingId} data-status={status} data-connection={connection}>
      <header className="bds-execution__header">
        <div><h2 id={headingId}>{title}</h2><code>{executionId}</code></div>
        <span className="bds-execution__status" role="status"><StatusIcon size={16} aria-hidden="true" />{labels[status]}</span>
      </header>
      <div className="bds-execution__bridge" aria-hidden="true"><span /></div>
      <div className="bds-execution__toolbar"><span><Terminal size={15} aria-hidden="true" /> Execution output</span><span>{events.length} events</span></div>
      {connection !== "connected" && <div className="bds-execution__connection" role="status"><TriangleAlert size={16} aria-hidden="true" /><p>{connection === "reconnecting" ? "Reconnecting. Output may be delayed." : "Connection lost. The execution may still be running."}</p>{onReconnect && connection === "disconnected" && <BfButton variant="secondary" onClick={onReconnect}>Reconnect</BfButton>}</div>}
      <div className="bds-execution__viewport" ref={viewport} role="region" aria-label="Execution events" tabIndex={0} onScroll={() => {
        const node = viewport.current;
        if (!node) return;
        const atBottom = node.scrollHeight - node.scrollTop - node.clientHeight < 24;
        following.current = atBottom;
        setFollowing(atBottom);
      }}>
        {events.length ? <ol className="bds-execution__events">{events.map((event) => <li key={event.id} data-level={event.level}><time>{event.time}</time><span className="bds-execution__level">{event.level}</span><code>{event.message}</code></li>)}</ol> : <p className="bds-execution__empty">{emptyMessage}</p>}
      </div>
      <footer className="bds-execution__footer"><span>{!isFollowing ? "Reading earlier output" : connection !== "connected" ? "Showing received output" : status === "running" ? "Following live output" : "End of received output"}</span>{!isFollowing && <BfButton variant="ghost" onClick={followLatest} icon={<ArrowDown size={14} />}>Jump to latest</BfButton>}</footer>
    </section>
  );
}

@import "./components.css";

.bds-execution { min-width: 0; overflow: hidden; border: 1px solid var(--bf-line); border-radius: var(--bf-radius-feature); background: var(--bf-paper); color: var(--bf-ink); font-family: var(--bf-font-sans); }
.bds-execution__header { display: flex; align-items: center; justify-content: space-between; gap: 20px; padding: 24px; background: var(--bf-surface-raised); }
.bds-execution__header h2 { margin: 0 0 6px; font-size: 18px; font-weight: 600; line-height: 1.4; overflow-wrap: anywhere; }
.bds-execution__header code { color: var(--bf-muted); font: 12px var(--bf-font-mono); overflow-wrap: anywhere; }
.bds-execution__status { display: inline-flex; flex: none; align-items: center; gap: 7px; font-size: 12px; font-weight: 600; }
.bds-execution[data-status="succeeded"] .bds-execution__status { color: var(--bf-success); }
.bds-execution[data-status="failed"] .bds-execution__status { color: var(--bf-danger); }
.bds-execution__bridge { height: 2px; overflow: hidden; background: var(--bf-line); }
.bds-execution__bridge span { display: block; width: 200%; height: 100%; background: var(--bf-bridge); background-size: 50% 100%; opacity: 0; }
.bds-execution[data-status="running"][data-connection="connected"] .bds-execution__bridge span { opacity: 1; animation: bf-stream-transfer var(--bf-motion-progress) linear infinite; }
.bds-execution__toolbar { display: flex; justify-content: space-between; align-items: center; gap: 16px; padding: 14px 24px; border-bottom: 1px solid var(--bf-line); color: var(--bf-muted); font-size: 12px; }
.bds-execution__toolbar > span:first-child { display: flex; align-items: center; gap: 8px; }
.bds-execution__viewport { height: 340px; min-height: 0; overflow: auto; overscroll-behavior: contain; scrollbar-color: var(--bf-line-strong) transparent; }
.bds-execution__viewport:focus-visible { outline: 2px solid var(--bf-primary); outline-offset: -2px; }
.bds-execution__events { margin: 0; padding: 16px 24px; list-style: none; }
.bds-execution__events li { display: grid; grid-template-columns: 72px 64px minmax(0, 1fr); gap: 14px; padding: 9px 0; font-size: 12px; line-height: 1.65; }
.bds-execution__events time { color: var(--bf-muted); font-family: var(--bf-font-mono); font-variant-numeric: tabular-nums; }
.bds-execution__events code { font-family: var(--bf-font-mono); white-space: pre-wrap; overflow-wrap: anywhere; }
.bds-execution__level { color: var(--bf-muted); }
.bds-execution__events [data-level="success"] .bds-execution__level { color: var(--bf-success); }
.bds-execution__events [data-level="warning"] .bds-execution__level { color: var(--bf-warning); }
.bds-execution__events [data-level="error"] .bds-execution__level { color: var(--bf-danger); }
.bds-execution__connection { display: flex; align-items: center; gap: 12px; padding: 12px 24px; color: var(--bf-warning); background: var(--bf-warning-soft); border-bottom: 1px solid var(--bf-line); }
.bds-execution__connection > svg { flex: none; }
.bds-execution__connection p { flex: 1; margin: 0; font-size: 13px; }
.bds-execution__empty { padding: 44px 24px; margin: 0; color: var(--bf-muted); font-size: 13px; }
.bds-execution__footer { display: flex; align-items: center; justify-content: space-between; gap: 12px; min-height: 56px; padding: 8px 24px; border-top: 1px solid var(--bf-line); color: var(--bf-muted); font-size: 12px; }
@keyframes bf-stream-transfer { to { transform: translateX(-50%); } }
@media (max-width: 620px) {
  .bds-execution__header { padding: 20px 16px; align-items: flex-start; flex-direction: column; gap: 12px; }
  .bds-execution__toolbar, .bds-execution__footer { padding-inline: 16px; }
  .bds-execution__events { padding: 12px 16px; }
  .bds-execution__events li { grid-template-columns: 72px 1fr; gap: 2px 12px; padding: 12px 0; }
  .bds-execution__events code { grid-column: 1 / -1; }
  .bds-execution__connection { flex-wrap: wrap; padding: 12px 16px; }
  .bds-execution__footer { flex-wrap: wrap; }
}
@media (prefers-reduced-motion: reduce) {
  .bds-execution[data-status="running"][data-connection="connected"] .bds-execution__bridge span { animation: none; }
}
